"""Preserve the full Radau stamp/state; change only the correction solver."""
import ast,base64,json,re,subprocess
from prepare_vco1_portable import ROOT,sha,write
from joint_cycles_analysis import require
ATTR=b'\n/tools/dynamic_schur_solver.rs text eol=lf\n/tools/joint_dynamic_schur_kernel.rs text eol=lf\n/tools/dynamic_schur_bench.rs text eol=lf\n/tools/joint_dynamic_schur_runner.rs text eol=lf\n'
def maps():
 text=(ROOT/'crates/rf-d-circuit/src/vco1_stamp_data.rs').read_text(encoding='utf8');m=re.search(r'OPAMPS:.*?= (\[\[.*?\]\]);',text);require(m is not None,'documented partition');raw=ast.literal_eval(m.group(1));map_node=lambda k:k if k<108 else k-1
 inside=[[map_node(k)+stage*229 for stage in range(2) for k in row[5:]] for row in raw];ports=[[(-1 if k==134 else map_node(k)+stage*229) for stage in range(2) for k in row[:5]] for row in raw];eliminated=set(sum(inside,[]));external=[k for k in range(458) if k not in eliminated];require(len(eliminated)==128 and len(external)==330,'partition dimensions');return inside,ports,external,raw
def kernel():
 s=(ROOT/'tools/joint_lu_extent_kernel.rs').read_text(encoding='utf8');a=s.index('pub fn step(');b=s.index('\nmod fine',a);s=s[:a]+s[a:b].replace('solve_linear_extent(','dynamic_schur::solve(')+s[b:];return s.replace('#[path="latch_charge_driver.rs"]','#[path="dynamic_schur_solver.rs"] pub mod dynamic_schur;\n#[path="latch_charge_driver.rs"]',1)
def caller():return (ROOT/'tools/joint_lu_extent_runner.rs').read_text(encoding='utf8').replace('path="joint_lu_extent_kernel.rs"','path="joint_dynamic_schur_kernel.rs"')
def main():
 head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip();require(head=='48543a753f4b538e798233a1f677addb7059526b','base');old=json.loads((ROOT/'evidence/voice_lu_extent_tests01.json').read_text(encoding='utf8'));require(old['passed'],'QA');write('evidence/voice_dynamic_schur_before01.json',dict(base_commit=head,previous_qa_sha256=sha(ROOT/'evidence/voice_lu_extent_tests01.json'),mutable_before_base64={n:base64.b64encode((ROOT/n).read_bytes()).decode() for n in ['.gitattributes','README.md','docs/PLAN.md','docs/MATRIZ_DE_FIDELIDAD.md']}));inside,ports,external,raw=maps();s=(ROOT/'tools/dynamic_schur_solver.rs').read_text(encoding='utf8');require('const INNER' in s,'solver partition');s=s.replace('/*INNER*/',str(inside).replace(' ','')).replace('/*PORTS*/',str(ports).replace('-1','usize::MAX').replace(' ','')).replace('/*EXTERNAL*/',str(external).replace(' ',''));(ROOT/'tools/dynamic_schur_solver.rs').write_text(s,encoding='utf8',newline='\n')
 for n,s in [('tools/joint_dynamic_schur_kernel.rs',kernel()),('tools/joint_dynamic_schur_runner.rs',caller())]:
  p=ROOT/n;require(not p.exists(),'exclusive source');p.write_text(s,encoding='utf8',newline='\n')
 p=ROOT/'.gitattributes';p.write_bytes(p.read_bytes()+ATTR);packet='references-local/newton-reuse-inputs01/pairs.bin';require(sha(ROOT/packet)==old['private_input_sha256'][packet],'frozen pairs');write('evidence/voice_dynamic_schur_inputs01.json',dict(passed=True,source_sha256={n:sha(ROOT/n) for n in ['tools/prepare_dynamic_schur.py','tools/dynamic_schur_solver.rs','tools/joint_dynamic_schur_kernel.rs','tools/joint_dynamic_schur_runner.rs','docs/SCHUR_DINAMICO_PROTOCOLO.md','crates/rf-d-circuit/src/vco1_stamp_data.rs']},private_used_sha256={packet:sha(ROOT/packet)},pair_packet=packet,selected_pairs=84,interiors=inside,ports=ports,external=external,original_opamp_maps=raw,seeds=json.loads((ROOT/'evidence/voice_lu_extent_inputs01.json').read_text(encoding='utf8'))['seeds']));print('DYNAMIC_SCHUR_INPUTS',128,330)
if __name__=='__main__':main()
